262:         {
263:             GeneralCoordinateSystem transportCoordinateSystem = (GeneralCoordinateSystem)MachineCoordinateSystem
264:                 .GetInstance().CoordinateSystems.Find(it => it.Name == "TransportCoordinateSystem");
265: 
266:             if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
267:             {
