282:         /// <summary>
283:         /// 初始化坐标系
284:         /// </summary>
285:         public void InitSubstrateCoordinateSystem()
286:         {
287:             SubstrateConfig substrateConfig = ProductConfiguration.GetInstance().SubstrateConfig;
288: 
289:             this.Substrates.Clear();
290: 
291:             if (!substrateConfig.IsMultiple)
292:             {
293:                 substrateConfig.Count = 1;
294:                 substrateConfig.ColumnCount = 1;
295:                 substrateConfig.RowCount = 1;
296:                 substrateConfig.ElementCoordinates.Clear();
297:                 substrateConfig.ElementCoordinates.Add(new ElementCoordinate());
298:             }
299: 
300:             // 如果没有，初始化一个
301:             if (substrateConfig.ElementCoordinates.Count == 0)
302:             {
303:                 substrateConfig.ElementCoordinates.Add(new ElementCoordinate());
304:             }
305: 
306:             if (substrateConfig.IsAssistanceDistanceByInput)
307:             {
308:                 ElementCoordinate elementCoordinateFirst = substrateConfig.ElementCoordinates[0];
309:                 substrateConfig.ElementCoordinates.Clear();
310: 
311:                 for (int i = 0; i < substrateConfig.RowCount; i++)
312:                 {
313:                     for (int j = 0; j <substrateConfig.ColumnCount; j++)
314:                     {
315:                         // Z轴的位置是跟随TU的，如果需要设置，需要到单独的测高界面
316:                         ElementCoordinate elementCoordinate = new ElementCoordinate();
317:                         elementCoordinate.Point = new AKRSPoint3D(
318:                             elementCoordinateFirst.Point.X + substrateConfig.ColumnSpacing * j,
319:                             elementCoordinateFirst.Point.Y + substrateConfig.RowSpacing * i,
320:                             elementCoordinateFirst.Point.Z);
321:                         elementCoordinate.Degree = 0;
322:                         substrateConfig.ElementCoordinates.Add(elementCoordinate);
323:                     }
324:                 }
325:             }
326: 
327:             for (int i = 0; i < substrateConfig.Count; i++)
328:             {
329:                 Substrate substrate = new Substrate(i + 1, this.CoordinateSystem);
330: 
331:                 // 判断行列数
332:                 if (substrateConfig.Multiplication == MultiplicationEnum.Matrix)
333:                 {
334:                     (substrate.RowIndex, substrate.ColumnIndex) = TuService.RowAndColumn(
335:                         substrateConfig.RowCount,
336:                         substrateConfig.ColumnCount,
337:                         i + 1,
338:                         substrateConfig.Arrangement);
339:                 }
340: 
341:                 this.Substrates.Add(substrate);
342:             }
343:         }
