887:         public static void ModifyMatter(TransportUnit transportUnit, OtherConfig config)
888:         {
889:             try
890:             {
891:                 if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
892:                 {
893:                     foreach (Substrate substrate in transportUnit.Substrates)
894:                     {
895:                         foreach (Module module in substrate.Modules)
896:                         {
897:                             foreach (BondPosition bondPosition in module.BondPositions)
898:                             {
899:                                 bondPosition.MatterProductState = bondPosition.OppositeSex.MatterProductState;
900:                             }
901:                         }
902:                     }
903:                 }
904:                 else
905:                 {
906:                     if (ProductConfiguration.GetInstance().TransportUnitConfig.LagerNumber)
907:                     {
908:                         foreach (Substrate substrate in transportUnit.Substrates)
909:                         {
910:                             foreach (Module module in substrate.Modules)
911:                             {
912:                                 module.SubstrateNum = substrate.Index;
913:                                 foreach (BondPosition bondPosition in module.BondPositions)
914:                                 {
915:                                     bondPosition.SubstrateNum = substrate.Index;
916:                                     bondPosition.ModuleNum = module.Index;
917: 
918:                                     List<MatterProductInformationMin> MatterProductInformationMins = config.MatterProductInfoMax[substrate.Index - 1][module.Index - 1];
919: 
920:                                     MatterProductInformationMin matterProductInformationMin = MatterProductInformationMins.Find(it => it.BondPositionName == bondPosition.Name);
921:                                     bondPosition.MatterProductState = matterProductInformationMin.MatterProductState;
922:                                 }
923:                             }
924:                         }
925:                     }
926:                     else
927:                     {
928:                         foreach (Substrate substrate in transportUnit.Substrates)
929:                         {
930:                             foreach (Module module in substrate.Modules)
931:                             {
932:                                 module.SubstrateNum = substrate.Index;
933:                                 foreach (BondPosition bondPosition in module.BondPositions)
934:                                 {
935:                                     bondPosition.SubstrateNum = substrate.Index;
936:                                     bondPosition.ModuleNum = module.Index;
937:                                     if (config.MatterProductInfo.Exists(
938:                                             it => it.SubstrateIndex == substrate.Index && it.ModuleIndex == module.Index
939:                                                   && it.BondPositionName == bondPosition.Name))
940:                                     {
941:                                         MatterProductInformation matterProductInformation = config.MatterProductInfo.Find(
942:                                             it => it.SubstrateIndex == substrate.Index && it.ModuleIndex == module.Index
943:                                                   && it.BondPositionName == bondPosition.Name);
944:                                         bondPosition.MatterProductState = matterProductInformation.MatterProductState;
945:                                     }
946:                                 }
947:                             }
948:                         }
949:                     }
950:                 }
951:             }
952:             catch (Exception e)
953:             {
954:                 config.ClearInformation();
955:                 ProductConfiguration.GetInstance().Save();
956:             }
957:         }

