859:         public void InjectSteps(TransportUnit transportUnit)
860:         {
861:             foreach (Substrate substrate in transportUnit.Substrates)
862:             {
863:                 foreach (Module module in substrate.Modules)
864:                 {
865:                     foreach (BondPosition bondPosition in module.BondPositions)
866:                     {
867:                         foreach (SingleProcessStep singleProcessStep in this.ProcessSteps)
868:                         {
869:                             if (singleProcessStep.BondPositionName == bondPosition.Name)
870:                             {
871:                                 if (!bondPosition.BondPositionInfo.S1RemainingSteps.ContainsKey(singleProcessStep.ProcessStepName))
872:                                 {
873:                                     bondPosition.BondPositionInfo.S1RemainingSteps.Add(
874:                                         singleProcessStep.ProcessStepName,
875:                                         false);
876:                                 }
877:                             }
878:                         }
879:                     }
880:                 }
881:             }
882:         }

