104:         public void CreateModule()
105:         {
106:             ModuleConfig moduleConfig = ProductConfiguration.GetInstance().ModuleConfig;
107: 
108:             if (!moduleConfig.IsMultiple)
109:             {
110:                 moduleConfig.Count = 1;
111:                 moduleConfig.ColumnCount = 1;
112:                 moduleConfig.RowCount = 1;
113:                 moduleConfig.ElementCoordinates.Clear();
114:                 moduleConfig.ElementCoordinates.Add(new ElementCoordinate());
115:             }
116: 
117:             // 如果没有，初始化一个
118:             if (moduleConfig.ElementCoordinates.Count == 0)
119:             {
120:                 moduleConfig.ElementCoordinates.Add(new ElementCoordinate());
121:             }
122: 
123:             if (moduleConfig.IsAssistanceDistanceByInput)
124:             {
125:                 ElementCoordinate elementCoordinateFirst = moduleConfig.ElementCoordinates[0];
126:                 moduleConfig.ElementCoordinates.Clear();
127: 
128:                 for (int i = 0; i < moduleConfig.RowCount; i++)
129:                 {
130:                     for (int j = 0; j < moduleConfig.ColumnCount; j++)
131:                     {
132:                         // Z轴的位置是跟随TU的，如果需要设置，需要到单独的测高界面
133:                         ElementCoordinate elementCoordinate = new ElementCoordinate();
134:                         elementCoordinate.Point = new AKRSPoint3D(
135:                             elementCoordinateFirst.Point.X + moduleConfig.ColumnSpacing * j,
136:                             elementCoordinateFirst.Point.Y + moduleConfig.RowSpacing * i,
137:                             elementCoordinateFirst.Point.Z);
138:                         elementCoordinate.Degree = 0;
139:                         moduleConfig.ElementCoordinates.Add(elementCoordinate);
140:                     }
141:                 }
142:             }
143: 
144:             for (int i = 0; i < moduleConfig.Count; i++)
145:             {
146:                 Module module = new Module(
147:                     i + 1,
148:                     this.CoordinateSystem);
149: 
150:                 // 判断行列数
151:                 if (moduleConfig.Multiplication == MultiplicationEnum.Matrix)
152:                 {
153:                     (module.RowIndex, module.ColumnIndex) = TuService.RowAndColumn(
154:                         moduleConfig.RowCount,
155:                         moduleConfig.ColumnCount,
156:                         i + 1,
157:                         moduleConfig.Arrangement);
158:                 }
159: 
160:                 this.Modules.Add(module);
161:             }
162:         }
