522:             // 基板的位置集合
523:             this.substrateConfig.ElementCoordinates = new List<ElementCoordinate>();
524: 
525:             if (this.substrateConfig.Multiplication == MultiplicationEnum.Matrix)
526:             {
527:                 this.substrateConfig.Count = this.substrateConfig.ColumnCount * this.substrateConfig.RowCount;
