535:                         elementCoordinate.Point = new AKRSPoint3D(
536:                             this.realOriginPos[0].X + this.distanceStartX + this.substrateConfig.ColumnSpacing * j + this.rowSpacingX * i,
537:                             this.realOriginPos[0].Y + this.distanceStartY + this.substrateConfig.RowSpacing * i + this.columnSpacingY * j,
538:                             this.realHeight);
539:                         elementCoordinate.Degree = 0;
540:                         this.substrateConfig.ElementCoordinates.Add(elementCoordinate);
541:                     }
542:                 }
543:             }
544:             else
545:             {
546:                 this.substrateConfig.Count = this.realOriginPos.Count;
547: 
548:                 for (int i = 0; i < this.realOriginPos.Count; i++)
549:                 {
550:                     ElementCoordinate elementCoordinate = new ElementCoordinate() {Point = this.realOriginPos[i]};
